SELECT 'contagens_preservadas' AS verificacao,jsonb_build_object('clientes',(SELECT count(*) FROM public.clientes),'enderecos',(SELECT count(*) FROM public.enderecos),'pedidos',(SELECT count(*) FROM public.pedidos),'itens',(SELECT count(*) FROM public.itens_pedido))::text AS resultado
UNION ALL SELECT 'operador_habilitado',jsonb_build_object('email',u.email,'papel',o.papel,'ativo',o.ativo)::text FROM public.pdv_operadores o JOIN auth.users u ON u.id=o.user_id
UNION ALL SELECT 'colunas_pedidos',jsonb_agg(column_name)::text FROM information_schema.columns WHERE table_schema='public' AND table_name='pedidos' AND column_name IN ('versao','finalizado_em','telefone_contato')
UNION ALL SELECT 'endereco_view',jsonb_agg(column_name)::text FROM information_schema.columns WHERE table_schema='public' AND table_name='vw_pedidos_completos' AND column_name IN ('endereco_numero','endereco_complemento','endereco_bairro','endereco_cidade','endereco_estado','versao')
UNION ALL SELECT 'acesso_anonimo_tabelas',jsonb_object_agg(c.relname,has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE'))::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('clientes','enderecos','pedidos','itens_pedido','produtos','categorias','cores','formas_pagamento','tipos_atendimento','configuracoes_empresa','tblClientes','tblPedidos','tblItensPedidos','tblProdutos','tblCores')
UNION ALL SELECT 'escrita_direta_auth',jsonb_object_agg(c.relname,has_table_privilege('authenticated',c.oid,'INSERT,UPDATE,DELETE'))::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('clientes','enderecos','pedidos','itens_pedido')
UNION ALL SELECT 'views_protegidas',jsonb_object_agg(c.relname,jsonb_build_object('invoker',c.reloptions,'anon_select',has_table_privilege('anon',c.oid,'SELECT')))::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='v'
UNION ALL SELECT 'rls_tabelas',jsonb_object_agg(c.relname,c.relrowsecurity)::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('clientes','enderecos','pedidos','itens_pedido','pdv_operadores','pdv_requisicoes','tblClientes','tblPedidos','tblItensPedidos','tblProdutos','tblCores')
UNION ALL SELECT 'rpc_anonima',jsonb_object_agg(p.proname,has_function_privilege('anon',p.oid,'EXECUTE'))::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND (p.proname LIKE 'pdv_%' OR p.proname IN ('duplicar_pedido','obter_proximo_numero_pedido','relatorio_vendas_anual','relatorio_vendas_periodo','top_produtos_vendidos'));